def _check_contract_lifecycle_assertions(snapshot):
    return _contract_check_lifecycle_assertions(
        snapshot, CONTRACT_LIFECYCLE_ASSERTION_PLAN, _CONTRACT_LIFECYCLE_STATE
    )

def _finalize_contract_lifecycle_assertions():
    return _contract_finalize_lifecycle_assertions(
        CONTRACT_LIFECYCLE_ASSERTION_PLAN, _CONTRACT_LIFECYCLE_STATE
    )

def _check_contract_assertions(snapshot):
    completed_stalls = _check_contract_protocol_assertions(snapshot)
    _check_contract_lifecycle_assertions(snapshot)
    return completed_stalls

def _finalize_contract_assertions():
    _finalize_contract_protocol_assertions()
    _finalize_contract_lifecycle_assertions()

async def _contract_generated_monitor(dut):
    """Observe the interface once and share it with assertions and coverage."""
    clock = getattr(dut, 'clk')
    while True:
        await Edge(clock)
        # Drivers update READY/VALID just after the falling edge. Sample
        # after their one-picosecond settling step, before the next edge.
        await Timer(2, unit='ps')
        await ReadOnly()
        if int(clock.value) != 0:
            reset_snapshot = capture_contract_snapshot(dut, ('rst_n',))
            if reset_snapshot:
                observe_contract_reset_snapshot(
                    reset_snapshot, _check_contract_assertions
                )
            continue
        snapshot = capture_contract_snapshot(dut, CONTRACT_SIGNAL_NAMES)
        sample_contract_snapshot(snapshot, _check_contract_assertions)

@_contract_cocotb.test(timeout_time=3600, timeout_unit='sec')
@_contract_coverage()
async def _contract_automatic_verification_campaign(dut):
    """Execute all code-owned operation/protocol/lifecycle scope."""
    return await _contract_run_code_owned_verification_campaign(
        dut,
        CONTRACT_PROTOCOL_STIMULUS_PLAN['interface_contract'],
        CONTRACT_OPERATION_METADATA,
        CONTRACT_LIFECYCLE_STIMULUS_PLAN,
        randomized_count=CONTRACT_AUTOMATIC_CAMPAIGN_CONFIG['randomized_transactions_minimum'],
        seed=CONTRACT_AUTOMATIC_CAMPAIGN_CONFIG['seed'],
    )

